\begin{tikzpicture}[font=\sffamily, scale=0.9]
    % --- Left Beaker (Zinc) ---
    \draw[thick] (1,0) -- (1,3) -- (3,3) -- (3,0);
    \node[below] at (2,0) {Zinc};
    \dotregion{1.1}{0.1}{2.9}{2.2}
    \draw[thick] (1.1,2.2) -- (2.9,2.2);
    \node[above] at (2,2.2) {\small $\text{Zn}^{2+}(\text{aq})$};

    % Zinc Electrode
    \draw[thick, fill=lightgray!40] (1.7,0.8) rectangle (2.3,3.8);
    \node[above] at (2,3.8) {Zn};

    % --- Right Beaker (Copper) ---
    \draw[thick] (7,0) -- (7,3) -- (9,3) -- (9,0);
    \node[below] at (8,0) {Copper};
    \dotregion{7.1}{0.1}{8.9}{2.2}
    \draw[thick] (7.1,2.2) -- (8.9,2.2);
    \node[above] at (8,2.2) {\small $\text{Cu}^{2+}(\text{aq})$};

    % Copper Electrode
    \draw[thick, fill=lightgray!40] (7.7,0.8) rectangle (8.3,3.8);
    \node[above] at (8,3.8) {Cu};

    % --- Salt Bridge ---
    \draw[thick, rounded corners=4pt] (2.5,2.5) -- (2.5,4.2) -- (5.0,4.5) -- (7.5,4.2) -- (7.5,2.5);
    \draw[thick, rounded corners=4pt] (2.5,2.1) -- (2.5,3.9) -- (5.0,4.2) -- (7.5,3.9) -- (7.5,2.1);
    % Plugs at ends of salt bridge
    \fill[gray!60] (2.4,2.2) rectangle (2.6,2.8);
    \fill[gray!60] (7.4,2.2) rectangle (7.6,2.8);
    \node[above] at (5,4.5) {Salt bridge};

    % --- External Circuit (Voltmeter) ---
    \draw[thick] (2,3.8) -- (2,5.2) -- (4.2,5.2);
    \draw[thick] (8,3.8) -- (8,5.2) -- (5.8,5.2);

    % Voltmeter Circle
    \draw[thick, fill=white] (5,5.2) circle (0.8cm);
    \node at (5,5.2) {\textbf{V}};

    % --- Labels and Captions ---
    \node at (5,-1.0) {Fig. 6.1};
\end{tikzpicture}

\begin{tikzpicture}[font=\sffamily, scale=0.9]
    % --- Left Beaker (Zinc) ---
    \draw[thick] (1,0) -- (1,3) -- (3,3) -- (3,0);
    \node[below] at (2,0) {Zinc};
    \dotregion{1.1}{0.1}{2.9}{2.2}
    \draw[thick] (1.1,2.2) -- (2.9,2.2);
    \node[above] at (2,2.2) {\small $\text{Zn}^{2+}(\text{aq})$};

    % Zinc Electrode
    \draw[thick, fill=lightgray!40] (1.7,0.8) rectangle (2.3,3.8);
    \node[above] at (2,3.8) {Zn};

    % --- Right Beaker (Copper) ---
    \draw[thick] (7,0) -- (7,3) -- (9,3) -- (9,0);
    \node[below] at (8,0) {Copper};
    \dotregion{7.1}{0.1}{8.9}{2.2}
    \draw[thick] (7.1,2.2) -- (8.9,2.2);
    \node[above] at (8,2.2) {\small $\text{Cu}^{2+}(\text{aq})$};

    % Copper Electrode
    \draw[thick, fill=lightgray!40] (7.7,0.8) rectangle (8.3,3.8);
    \node[above] at (8,3.8) {Cu};

    % --- Salt Bridge (U-tube dipping into solutions) ---
    \draw[thick, rounded corners=6pt] (3.2,1.8) -- (3.2,3.5) -- (5.0,3.8) -- (6.8,3.5) -- (6.8,1.8);
    \draw[thick, rounded corners=6pt] (3.5,1.8) -- (3.5,3.2) -- (5.0,3.5) -- (6.5,3.2) -- (6.5,1.8);
    % Salt bridge contents shading/label
    \node[above] at (5,3.8) {Salt bridge};

    % --- External Circuit (Voltmeter) ---
    \draw[thick] (2,3.8) -- (2,5.2) -- (4.2,5.2);
    \draw[thick] (8,3.8) -- (8,5.2) -- (5.8,5.2);

    % Voltmeter Circle
    \draw[thick, fill=white] (5,5.2) circle (0.8cm);
    \node at (5,5.2) {\textbf{V}};

    % --- Labels and Captions ---
    \node at (5,-1.0) {Fig. 6.1};
\end{tikzpicture}
